import { createRoute, z } from '@hono/zod-openapi'

const NestedContactGroupSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
    url: z.url().openapi({ readOnly: true }),
    display_url: z.url().openapi({ readOnly: true }),
    display: z.string().openapi({ readOnly: true }),
    name: z.string().max(100),
    slug: z
      .string()
      .regex(/^[-a-zA-Z0-9_]+$/)
      .max(100),
    _depth: z.int().openapi({ readOnly: true, title: ' depth' }),
  })
  .openapi({
    description:
      'Represents an object related through a ForeignKey field. On write, it accepts a primary key (PK) value or a\ndictionary of attributes which can be used to uniquely identify the related object. This class should be\nsubclassed to return a full representation of the related object on read.',
    required: ['_depth', 'display', 'display_url', 'id', 'name', 'slug', 'url'],
  })
  .openapi('NestedContactGroup')

