const BriefIPAddressSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
    url: z.url().openapi({ readOnly: true }),
    display: z.string().openapi({ readOnly: true }),
    family: z
      .object({
        value: z
          .union([z.literal(4), z.literal(6)])
          .exactOptional()
          .openapi({
            description: '* `4` - IPv4\n* `6` - IPv6',
            'x-spec-enum-id': 'd72003fd1af3603d',
          }),
        label: z.enum(['IPv4', 'IPv6']).exactOptional(),
      })
      .openapi({ readOnly: true, required: [] }),
    address: z.string(),
    nat_inside: NestedIPAddressSchema.nullable().exactOptional(),
    nat_outside: z.array(NestedIPAddressSchema).openapi({ readOnly: true }),
    dns_name: z
      .xor([
        z
          .string()
          .regex(/^([0-9A-Za-z_-]+|\*)(\.[0-9A-Za-z_-]+)*\.?$/)
          .max(255),
        z.string().max(0),
      ])
      .exactOptional()
      .openapi({ description: 'Hostname or FQDN (not case-sensitive)' }),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['address', 'display', 'family', 'id', 'nat_outside', 'url'],
  })
  .openapi('BriefIPAddress')

