type DeviceType = {
  id: bigint
  url: string
  display_url: string
  display: string
  name?: string | null
  device_type: z.infer<typeof BriefDeviceTypeSchema>
  role: z.infer<typeof BriefDeviceRoleSchema>
  tenant?: z.infer<typeof BriefTenantSchema> | null
  platform?: z.infer<typeof BriefPlatformSchema> | null
  serial?: string
  asset_tag?: string | null
  site: z.infer<typeof BriefSiteSchema>
  location?: z.infer<typeof BriefLocationSchema> | null
  rack?: z.infer<typeof BriefRackSchema> | null
  position?: number | null
  face?: { value?: 'front' | 'rear' | ''; label?: 'Front' | 'Rear' }
  latitude?: number | null
  longitude?: number | null
  parent_device: z.infer<typeof NestedDeviceSchema> | null
  status?: {
    value?: 'offline' | 'active' | 'planned' | 'staged' | 'failed' | 'inventory' | 'decommissioning'
    label?: 'Offline' | 'Active' | 'Planned' | 'Staged' | 'Failed' | 'Inventory' | 'Decommissioning'
  }
  airflow?: {
    value?:
      | 'front-to-rear'
      | 'rear-to-front'
      | 'left-to-right'
      | 'right-to-left'
      | 'side-to-rear'
      | 'rear-to-side'
      | 'bottom-to-top'
      | 'top-to-bottom'
      | 'passive'
      | 'mixed'
      | ''
    label?:
      | 'Front to rear'
      | 'Rear to front'
      | 'Left to right'
      | 'Right to left'
      | 'Side to rear'
      | 'Rear to side'
      | 'Bottom to top'
      | 'Top to bottom'
      | 'Passive'
      | 'Mixed'
  }
  cooling_method?: {
    value?: 'air' | 'liquid' | 'hybrid' | 'immersion' | '' | null
    label?: 'Air' | 'Liquid' | 'Hybrid' | 'Immersion'
  } | null
  primary_ip: z.infer<typeof BriefIPAddressSchema> | null
  primary_ip4?: z.infer<typeof BriefIPAddressSchema> | null
  primary_ip6?: z.infer<typeof BriefIPAddressSchema> | null
  oob_ip?: z.infer<typeof BriefIPAddressSchema> | null
  cluster?: z.infer<typeof BriefClusterSchema> | null
  virtual_chassis?: z.infer<typeof BriefVirtualChassisSchema> | null
  vc_position?: number | null
  vc_priority?: number | null
  description?: string
  owner?: z.infer<typeof BriefOwnerSchema> | null
  comments?: string
  config_template?: z.infer<typeof BriefConfigTemplateSchema> | null
  config_context: { [key: string]: unknown } | null
  local_context_data?: { [key: string]: unknown } | null
  tags?: z.infer<typeof NestedTagSchema>[]
  custom_fields?: { [key: string]: unknown }
  created: string | null
  last_updated: string | null
  console_port_count: bigint
  console_server_port_count: bigint
  power_port_count: bigint
  power_outlet_count: bigint
  cooling_intake_count: bigint
  cooling_outflow_count: bigint
  interface_count: bigint
  front_port_count: bigint
  rear_port_count: bigint
  device_bay_count: bigint
  module_bay_count: bigint
  inventory_item_count: bigint
}

