const BriefDeviceRequestSchema = z
  .object({
    name: z.string().max(64).nullable().exactOptional(),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: [],
  })
  .openapi('BriefDeviceRequest')

const NestedModuleBayRequestSchema = z
  .object({ name: z.string().min(1).max(64) })
  .openapi({
    description:
      'Represents an object related through a ForeignKey field. On write, it accepts a primary key (PK) value or a\ndictionary of attributes which can be used to uniquely identify the related object. This class should be\nsubclassed to return a full representation of the related object on read.',
    required: ['name'],
  })
  .openapi('NestedModuleBayRequest')

const BriefModuleRequestSchema = z
  .object({
    device: z.xor([
      z
        .preprocess(
          (val) =>
            typeof val === 'number' && Number.isSafeInteger(val)
              ? BigInt(val)
              : typeof val === 'string' && /^-?\d+$/.test(val)
                ? BigInt(val)
                : val,
          z.int64(),
        )
        .openapi({ type: 'integer', format: 'int64' }),
      BriefDeviceRequestSchema,
    ]),
    module_bay: NestedModuleBayRequestSchema,
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['device', 'module_bay'],
  })
  .openapi('BriefModuleRequest')

const NestedInterfaceRequestSchema = z
  .object({
    name: z.string().min(1).max(64),
    cable: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({ type: ['integer', 'null'], format: 'int64' }),
  })
  .openapi({
    description:
      'Represents an object related through a ForeignKey field. On write, it accepts a primary key (PK) value or a\ndictionary of attributes which can be used to uniquely identify the related object. This class should be\nsubclassed to return a full representation of the related object on read.',
    required: ['name'],
  })
  .openapi('NestedInterfaceRequest')

const BriefMACAddressRequestSchema = z
  .object({ mac_address: z.string().min(1), description: z.string().max(200).exactOptional() })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['mac_address'],
  })
  .openapi('BriefMACAddressRequest')

const BriefVLANRequestSchema = z
  .object({
    vid: z
      .int()
      .min(1)
      .max(4094)
      .openapi({ title: 'VLAN ID', description: 'Numeric VLAN ID (1-4094)' }),
    name: z.string().min(1).max(64),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['name', 'vid'],
  })
  .openapi('BriefVLANRequest')

const BriefVLANTranslationPolicyRequestSchema = z
  .object({ name: z.string().min(1).max(100), description: z.string().max(200).exactOptional() })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['name'],
  })
  .openapi('BriefVLANTranslationPolicyRequest')

