const BriefModuleTypeProfileSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
    url: z.url().openapi({ readOnly: true }),
    display: z.string().openapi({ readOnly: true }),
    name: z.string().max(100),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['display', 'id', 'name', 'url'],
  })
  .openapi('BriefModuleTypeProfile')

const BriefModuleTypeSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
    url: z.url().openapi({ readOnly: true }),
    display: z.string().openapi({ readOnly: true }),
    profile: BriefModuleTypeProfileSchema.nullable().exactOptional(),
    manufacturer: BriefManufacturerSchema,
    model: z.string().max(100),
    description: z.string().max(200).exactOptional(),
    module_count: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['display', 'id', 'manufacturer', 'model', 'module_count', 'url'],
  })
  .openapi('BriefModuleType')

const NestedInterfaceTemplateSchema = z
  .object({
    id: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', readOnly: true }),
    url: z.url().openapi({ readOnly: true }),
    display: z.string().openapi({ readOnly: true }),
    name: z
      .string()
      .max(64)
      .openapi({
        description:
          '{module} is accepted as a substitution for the module bay position when attached to a module type.',
      }),
  })
  .openapi({
    description:
      'Represents an object related through a ForeignKey field. On write, it accepts a primary key (PK) value or a\ndictionary of attributes which can be used to uniquely identify the related object. This class should be\nsubclassed to return a full representation of the related object on read.',
    required: ['display', 'id', 'name', 'url'],
  })
  .openapi('NestedInterfaceTemplate')

