const BriefManufacturerRequestSchema = z
  .object({
    name: z.string().min(1).max(100),
    slug: z
      .string()
      .regex(/^[-a-zA-Z0-9_]+$/)
      .min(1)
      .max(100),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from OrganizationalModel.',
    required: ['name', 'slug'],
  })
  .openapi('BriefManufacturerRequest')

const BriefDeviceTypeRequestSchema = z
  .object({
    manufacturer: z.xor([
      z
        .preprocess(
          (val) =>
            typeof val === 'number' && Number.isSafeInteger(val)
              ? BigInt(val)
              : typeof val === 'string' && /^-?\d+$/.test(val)
                ? BigInt(val)
                : val,
          z.int64(),
        )
        .openapi({ type: 'integer', format: 'int64' }),
      BriefManufacturerRequestSchema,
    ]),
    model: z.string().min(1).max(100),
    slug: z
      .string()
      .regex(/^[-a-zA-Z0-9_]+$/)
      .min(1)
      .max(100),
    description: z.string().max(200).exactOptional(),
  })
  .openapi({
    description: 'Base serializer class for models inheriting from PrimaryModel.',
    required: ['manufacturer', 'model', 'slug'],
  })
  .openapi('BriefDeviceTypeRequest')

