export const postApiDcimDevicesIdRenderConfigIndexRoute = createRoute({
  method: 'post',
  path: '/api/dcim/devices/{id}/render-config/',
  tags: ['dcim'],
  description:
    'Resolve and render the preferred ConfigTemplate for this Device or Virtual Machine.',
  operationId: 'dcim_devices_render_config_create',
  request: {
    query: z.object({
      format: z
        .enum(['json', 'txt'])
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'format',
            schema: { type: 'string', enum: ['json', 'txt'] },
            required: false,
          },
        }),
    }),
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            schema: { type: 'integer', format: 'int64' },
            description: 'A unique integer value identifying this device.',
            required: true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': { schema: RenderConfigInputRequestSchema },
        'multipart/form-data': {
          schema: z
            .looseObject({
              config_template_id: z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64().max(9223372036854776000n))
                .exactOptional()
                .openapi({
                  type: 'integer',
                  format: 'int64',
                  maximum: 9223372036854776000,
                  description:
                    "Optional ID of the ConfigTemplate to render. If omitted, the object's assigned config template is used.",
                }),
            })
            .openapi({
              description:
                'Describes the request body for the device/VM /render-config/ endpoints. Any additional keys\nsupplied are passed through as context variables to the rendered template.',
              required: [],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description:
        'The rendered config template. When the client requests `text/plain`, the raw rendered content is returned in place of the JSON object.',
      content: {
        'application/json': { schema: RenderedConfigSchema },
        'text/plain': { schema: RenderedConfigSchema },
      },
    },
    400: {
      description: 'No config template could be resolved for this object.',
      content: {
        'application/json': { schema: z.record(z.string(), z.any()) },
        'text/plain': { schema: z.record(z.string(), z.any()) },
      },
    },
    500: {
      description: 'An error occurred while rendering the config template.',
      content: {
        'application/json': { schema: z.record(z.string(), z.any()) },
        'text/plain': { schema: z.record(z.string(), z.any()) },
      },
    },
  },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

