export const getApiDcimInterfaceTemplatesIdIndexRoute = createRoute({
  method: 'get',
  path: '/api/dcim/interface-templates/{id}/',
  tags: ['dcim'],
  description: 'Get a interface template object.',
  operationId: 'dcim_interface_templates_retrieve',
  request: {
    query: z.object({
      brief: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'brief',
            schema: { type: 'boolean' },
            description: 'Return only brief fields for each object.',
            required: false,
          },
        }),
      fields: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'fields',
            schema: { type: 'string' },
            description:
              'Comma-separated list of fields to include in the response. Example: `fields=id,name`.',
            required: false,
          },
        }),
      omit: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            in: 'query',
            name: 'omit',
            schema: { type: 'string' },
            description:
              'Comma-separated list of fields to exclude from the response. Example: `omit=description,tags`.',
            required: false,
          },
        }),
    }),
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            schema: { type: 'integer', format: 'int64' },
            description: 'A unique integer value identifying this interface template.',
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: InterfaceTemplateSchema } } },
  },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

