export const deleteApiDcimInterfacesIdIndexRoute = createRoute({
  method: 'delete',
  path: '/api/dcim/interfaces/{id}/',
  tags: ['dcim'],
  description: 'Delete a interface object.',
  operationId: 'dcim_interfaces_destroy',
  request: {
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            schema: { type: 'integer', format: 'int64' },
            description: 'A unique integer value identifying this interface.',
            required: true,
          },
        }),
    }),
  },
  responses: { 204: { description: 'No response body' } },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

