export const deleteApiDcimPowerPortTemplatesIdIndexRoute = createRoute({
  method: 'delete',
  path: '/api/dcim/power-port-templates/{id}/',
  tags: ['dcim'],
  description: 'Delete a power port template object.',
  operationId: 'dcim_power_port_templates_destroy',
  request: {
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            schema: { type: 'integer', format: 'int64' },
            description: 'A unique integer value identifying this power port template.',
            required: true,
          },
        }),
    }),
  },
  responses: { 204: { description: 'No response body' } },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

