export const postApiExtrasScriptsIdIndexRoute = createRoute({
  method: 'post',
  path: '/api/extras/scripts/{id}/',
  tags: ['extras'],
  description:
    'Run a Script identified by its numeric PK or module & name and return the pending Job as the result',
  operationId: 'extras_scripts_run',
  request: {
    params: z.object({
      id: z
        .string()
        .regex(/^[^\/]+$/)
        .openapi({
          param: {
            in: 'path',
            name: 'id',
            schema: { type: 'string', pattern: '^[^/]+$' },
            required: true,
          },
        }),
    }),
    body: {
      content: {
        'application/json': { schema: ScriptInputRequestSchema },
        'multipart/form-data': {
          schema: z
            .object({
              data: z.any(),
              commit: z.preprocess(
                ((read) => (val: unknown) => {
                  const result = read.safeParse(val)
                  return result.success ? result.data : val
                })(z.stringbool()),
                z.boolean(),
              ),
              schedule_at: ((schema) =>
                z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
                z.iso.datetime({ offset: true }).nullable(),
              ).exactOptional(),
              interval: z
                .preprocess(
                  (val) => (val === 'null' ? null : val),
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    )
                    .nullable(),
                )
                .exactOptional(),
              notifications: z
                .enum(['always', 'on_failure', 'never'])
                .default('always')
                .exactOptional()
                .openapi({
                  description:
                    '* `always` - Always\n* `on_failure` - On failure\n* `never` - Never',
                  'x-spec-enum-id': '57071f4400340a5c',
                }),
            })
            .openapi({ required: ['commit', 'data'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'The script has been enqueued for execution.',
      content: { 'application/json': { schema: ScriptDetailSchema } },
    },
  },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

