export const putApiUsersUsersIndexRoute = createRoute({
  method: 'put',
  path: '/api/users/users/',
  tags: ['users'],
  description: 'Put a list of user objects.',
  operationId: 'users_users_bulk_update',
  request: {
    body: {
      content: {
        'application/json': { schema: z.array(BulkUserRequestSchema) },
        'multipart/form-data': {
          schema: z.preprocess(
            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
            z.array(
              z
                .object({
                  id: z
                    .preprocess((val) => {
                      if (
                        typeof val !== 'string' ||
                        !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                      )
                        return val
                      if (/^-?\d+$/.test(val)) return BigInt(val)
                      const num = Number(val)
                      return Number.isSafeInteger(num) ? BigInt(num) : val
                    }, z.int64().max(9223372036854776000n))
                    .openapi({ type: 'integer', format: 'int64', maximum: 9223372036854776000 }),
                  username: z
                    .string()
                    .regex(/^[\w.@+-]+$/)
                    .min(1)
                    .max(150)
                    .openapi({
                      description:
                        'Required. 150 characters or fewer. Letters, digits and @/./+/-/_ only.',
                    }),
                  password: z.string().min(1).max(128).openapi({ writeOnly: true }),
                  first_name: z.string().max(150).exactOptional(),
                  last_name: z.string().max(150).exactOptional(),
                  email: z
                    .xor([z.email().max(254), z.string().max(0)])
                    .exactOptional()
                    .openapi({ title: 'Email address' }),
                  is_active: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      title: 'Active',
                      description:
                        'Designates whether this user should be treated as active. Unselect this instead of deleting accounts.',
                    }),
                  date_joined: z.iso.datetime({ offset: true }).exactOptional(),
                  last_login: ((schema) =>
                    z.union([
                      schema,
                      z.preprocess((val) => (val === 'null' ? null : val), schema),
                    ]))(z.iso.datetime({ offset: true }).nullable()).exactOptional(),
                  groups: z
                    .preprocess(
                      (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                      z.array(
                        z
                          .preprocess((val) => {
                            if (
                              typeof val !== 'string' ||
                              !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                            )
                              return val
                            if (/^-?\d+$/.test(val)) return BigInt(val)
                            const num = Number(val)
                            return Number.isSafeInteger(num) ? BigInt(num) : val
                          }, z.int64())
                          .openapi({ type: 'integer', format: 'int64' }),
                      ),
                    )
                    .exactOptional(),
                  permissions: z
                    .preprocess(
                      (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                      z.array(
                        z
                          .preprocess((val) => {
                            if (
                              typeof val !== 'string' ||
                              !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                            )
                              return val
                            if (/^-?\d+$/.test(val)) return BigInt(val)
                            const num = Number(val)
                            return Number.isSafeInteger(num) ? BigInt(num) : val
                          }, z.int64())
                          .openapi({ type: 'integer', format: 'int64' }),
                      ),
                    )
                    .exactOptional(),
                })
                .openapi({
                  description:
                    'Extends the built-in ModelSerializer to enforce calling full_clean() on a copy of the associated instance during\nvalidation. (DRF does not do this by default; see https://github.com/encode/django-rest-framework/issues/3144)\n\nSerializers may declare `model_clean_fields` in Meta, naming scalar model fields whose clean()-normalized values\nmust reach the database. DRF builds a fresh instance from the validated data on create, discarding what clean()\nwrote.',
                  required: ['id', 'password', 'username'],
                }),
            ),
          ),
        },
      },
      required: true,
    },
  },
  responses: {
    200: { description: '', content: { 'application/json': { schema: z.array(UserSchema) } } },
    400: {
      description:
        'One or more of the objects specified could not be updated. No objects were modified: a bulk update is an all-or-none operation.',
      content: { 'application/json': { schema: BulkOperationErrorSchema } },
    },
    403: {
      description:
        'The requesting user is not permitted to apply one or more of the modifications specified. No objects were modified.',
      content: { 'application/json': { schema: BulkOperationErrorSchema } },
    },
  },
  security: [{ cookieAuth: [] }, { tokenAuth: [] }],
})

